for (const k of ['dependencies','devDependencies','optionalDependencies','peerDependencies']) {
  if(!p[k]) continue;
  const hits=Object.entries(p[k]).filter(([n])=>/contentful/i.test(n));
  if(hits.length) console.log(k, JSON.stringify(Object.fromEntries(hits),null,2));
}
"

