  1	#!/usr/bin/env node
  2	/**
  3	 * Populate .env with Contentful API tokens fetched live from the space.
  4	 *
  5	 * Rules:
  6	 *   - Missing var  → added at the end of the Contentful block
  7	 *   - Empty var    → filled with the live value
  8	 *   - Wrong var    → updated with the live value
  9	 *   - CONTENTFUL_MANAGEMENT_TOKEN → never touched (per-user personal token)
 10	 *
 11	 * Write access (add/update) is gated to @ZimmermannAU/tier-1-approvers.
 12	 * Non-approvers get a read-only view of what the values should be.
 13	 *
 14	 * Usage:
 15	 *   npm run config:contentful               # update .env if authorised
 16	 *   npm run config:contentful -- --dry-run  # print changes without writing
 17	 */
 18	
 19	import { readFileSync, writeFileSync, existsSync } from 'fs';
 20	import { execSync } from 'child_process';
 21	import { resolve, dirname } from 'path';
 22	import { fileURLToPath } from 'url';
 23	import { checkEnv, createClient, log } from './_shared.mjs';
 24	
 25	const __dirname = dirname(fileURLToPath(import.meta.url));
 26	const REPO_ROOT = resolve(__dirname, '../../../');
 27	const ENV_FILE = resolve(REPO_ROOT, '.env');
 28	const DRY_RUN = process.argv.includes('--dry-run');
 29	
 30	const ENVIRONMENT_IDS = ['master', 'dev', 'test', 'sit', 'staging', 'uat'];
 31	const SKIP_VARS = new Set(['CONTENTFUL_MANAGEMENT_TOKEN']);
 32	
 33	// Vars managed by this script, keyed by their .env name
 34	const MANAGED_VARS = [
 35	  'CONTENTFUL_SPACE_ID',
 36	  'CONTENTFUL_ENVIRONMENT_ID',
 37	  'CONTENTFUL_DELIVERY_TOKEN',
 38	  'CONTENTFUL_PREVIEW_TOKEN',
 39	];
 40	
 41	checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
 42	
 43	// ── Tier 1 gate ──────────────────────────────────────────────────────────────
 44	
 45	async function isTier1Approver() {
 46	  try {
 47	    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
 48	    const membersRaw = execSync(
 49	      "gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'",
 50	      { encoding: 'utf8' },
 51	    ).trim();
 52	    const members = membersRaw.split('\n').filter(Boolean);
 53	    return { approved: members.includes(login), login };
 54	  } catch {
 55	    return { approved: false, login: 'unknown' };
 56	  }
 57	}
 58	
 59	// ── .env parsing ─────────────────────────────────────────────────────────────
 60	
 61	function parseEnv(content) {
 62	  return content.split('\n').map((line) => {
 63	    if (line.startsWith('#') || line.trim() === '') {
 64	      return { type: 'raw', value: line };
 65	    }
 66	    const eqIdx = line.indexOf('=');
 67	    if (eqIdx === -1) return { type: 'raw', value: line };
 68	    return { type: 'var', key: line.slice(0, eqIdx), value: line.slice(eqIdx + 1) };
 69	  });
 70	}
 71	
 72	function serializeEnv(entries) {
 73	  return entries.map((e) => (e.type === 'var' ? `${e.key}=${e.value}` : e.value)).join('\n');
 74	}
 75	
 76	// ── Main ─────────────────────────────────────────────────────────────────────
 77	
 78	async function main() {
 79	  const { approved, login } = await isTier1Approver();
 80	
 81	  if (!approved) {
 82	    log.warn(`Authenticated as '${login}' — not a tier-1-approver. Running in read-only mode.`);
