     1	#!/usr/bin/env node
     2	/**
     3	 * Promote a Contentful environment alias to a new target.
     4	 *
     5	 * Flips both the 'production' alias and the built-in 'master' alias
     6	 * atomically — they always stay in sync so neither points to a stale environment.
     7	 *
     8	 * Usage:
     9	 *   npm run promote:alias -- --target release-2025-08
    10	 *   npm run promote:alias -- --target release-2025-08 --dry-run
    11	 *
    12	 * Release workflow:
    13	 *   1. Create a release environment (clone master in Contentful web UI or via CMA)
    14	 *   2. Install the content model:  npm run install:contentful -- --target release-2025-08
    15	 *   3. Test via direct environment ID (bypasses alias)
    16	 *   4. Promote:         npm run promote:alias -- --target release-2025-08
    17	 *   5. Retain old environment for 14 days, then delete
    18	 */
    19	
    20	import { checkEnv, createClient, log } from './_shared.mjs';
    21	
    22	checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
    23	
    24	const args = process.argv.slice(2);
    25	const targetIdx = args.indexOf('--target');
    26	const TARGET = targetIdx !== -1 ? args[targetIdx + 1] : null;
    27	const DRY_RUN = args.includes('--dry-run');
    28	
    29	if (!TARGET) {
    30	  log.error('--target <environmentId> is required.');
    31	  console.error('  Example: npm run promote:alias -- --target release-2025-08\n');
    32	  process.exit(1);
    33	}
    34	
    35	const ALIASES_TO_FLIP = ['production', 'master'];
    36	
    37	async function main() {
    38	  const client = createClient();
    39	
    40	  // Verify the target environment exists and is ready
    41	  let targetEnv;
    42	  try {
    43	    targetEnv = await client.environment.get({ environmentId: TARGET });
    44	  } catch {
    45	    log.error(`Environment '${TARGET}' not found in space '${process.env.CONTENTFUL_SPACE_ID}'.`);
    46	    process.exit(1);
    47	  }
    48	
    49	  const status = targetEnv.sys.status?.sys?.id;
    50	  if (status !== 'ready') {
    51	    log.error(`Environment '${TARGET}' is not ready (status: ${status ?? 'unknown'}).`);
    52	    process.exit(1);
    53	  }
    54	
    55	  // Read current alias state
    56	  const { items: aliases } = await client.environmentAlias.getMany({});
    57	  const currentTargets = Object.fromEntries(aliases.map((a) => [a.sys.id, a.environment.sys.id]));
    58	
    59	  log.section('Alias promotion');
    60	  console.log(`  Target environment: ${TARGET}`);
    61	
    62	  for (const aliasId of ALIASES_TO_FLIP) {
    63	    const current = currentTargets[aliasId] ?? '(none)';
    64	    if (current === TARGET) {
    65	      log.skip(`Alias '${aliasId}' already points to '${TARGET}'`);
    66	      continue;
    67	    }
    68	    console.log(`  ${aliasId}: ${current} → ${TARGET}`);
    69	    if (!DRY_RUN) {
    70	      await client.environmentAlias.createOrUpdate(
    71	        { environmentAliasId: aliasId },
    72	        { environment: { sys: { type: 'Link', linkType: 'Environment', id: TARGET } } },
    73	      );
    74	      log.success(`Alias '${aliasId}' → '${TARGET}'`);
    75	    } else {
    76	      log.info(`[dry-run] Would flip alias '${aliasId}' → '${TARGET}'`);
    77	    }
    78	  }
    79	
    80	  if (!DRY_RUN) {
    81	    console.log(`\n  ✅  Production now points to '${TARGET}'.`);
    82	    console.log(`  ℹ️   Retain previous environment for 14 days before deleting.\n`);
    83	  }
    84	}
    85	
    86	main().catch((err) => {
    87	  log.error(err.message ?? err);
    88	  process.exit(1);
    89	});
